        UNION { VALUES ?root { wd:Q557770 wd:Q2739642 wd:Q285300 wd:Q27628368 wd:Q55633141 wd:Q203087 wd:Q5359789 wd:Q131363472 wd:Q184230 wd:Q7520826 wd:Q85827478 wd:Q2765700 wd:Q111568537 wd:Q109974205 wd:Q104413311 wd:Q7563772 wd:Q181593 wd:Q57241316 wd:Q4388728 wd:Q22205802 } ?item wdt:P279 ?root }
